@pytest.mark.parametrize("js", ASM_SPECS)
def test_fuzz_asm_layout_clean(js):
    """装配图：薄座板小比例时配合代号与总体尺寸相撞（总体尺寸外移 / A3 放大一档）；就近一侧引出。"""
    import tempfile

    from cadmcp.detailing import plan_assembly_drawing
    from cadmcp.gateway.service import CadService
    from cadmcp.ir import AssemblySpec
    d = json.loads(js)
    svc = CadService.from_config(None, None, tempfile.mkdtemp())
    svc.change_begin("F")
    for p_ in d["parts"]:
        svc.build(PartSpec.model_validate(p_))
    svc.build(AssemblySpec.model_validate(d["asm"]))
    a = svc._models()[d["asm"]["name"]].resolved
    plan = plan_assembly_drawing(DrawingSpec(model=d["asm"]["name"]), a)
    _, out = render(plan, a)
    assert out["crossings"] == [] and out["collisions"] == []
    from cadmcp.detailing import view_overlaps, dim_line_overlaps
    assert view_overlaps(plan) == [] and dim_line_overlaps(plan) == []
    W = plan.sheet_size[0]  # 轴测图不进右侧明细表一栏
    top = 5 + 56 + 12 + 5 * len(plan.notes) + (7 * (len(plan.bom) + 1) if plan.bom else 0)
    for v in plan.views:
        if v.type == "iso":
            assert v.origin_on_sheet[0] + v.size_mm[0] / 2 <= W - 185 or v.origin_on_sheet[1] - v.size_mm[1] / 2 >= top


def test_scale_label_keeps_decimal():
    from cadmcp.detailing import scale_label
    assert scale_label(0.4) == "1:2.5" and scale_label(0.25) == "1:4" and scale_label(2.5) == "2.5:1"


def test_asm_iso_draws_revolve_parts_as_cylinders():
    """装配轴测图：销按回转段画成圆柱（椭圆端面），不是方盒子；穿在板里的部分不画。"""
    import tempfile

    from cadmcp.detailing import plan_assembly_drawing
    from cadmcp.gateway.service import CadService
    from cadmcp.ir import AssemblySpec
    d = json.loads(ASM_SPECS[0])
    svc = CadService.from_config(None, None, tempfile.mkdtemp())
    svc.change_begin("F")
    for p_ in d["parts"]:
        svc.build(PartSpec.model_validate(p_))
    svc.build(AssemblySpec.model_validate(d["asm"]))
    a = svc._models()[d["asm"]["name"]].resolved
    plan = plan_assembly_drawing(DrawingSpec(model=d["asm"]["name"]), a)
    svg, _ = render(plan, a)
    big = [x for x in svg.split("<polygon")[1:] if "fill='white'" in x and x.split("'")[1].count(",") >= 30]
    assert len(big) >= 4  # 两个销 × (头部/杆部轮廓 + 端面椭圆)


def test_short_step_keeps_deviations():
    """短轴段放不下带偏差的直径文字：偏差照样写全（车间按数值加工检验），文字伸出轮廓并越过上方尺寸行。"""
    spec = json.loads('{"name": "S13", "part_no": "S-13", "title": "测试轴", "material": "45#", "base": {"type": "shaft", "chamfer": 0, "steps": [{"length": 25, "diameter": 27, "tolerance": "m6"}, {"length": 50, "diameter": 30, "tolerance": "js6"}]}, "features": [{"feature": "keyway", "name": "K0", "step": 0, "length": 18}, {"feature": "keyway", "name": "K1", "step": 1, "length": 36}]}')
    p = resolve_part(PartSpec.model_validate(spec))
    plan = plan_part_drawing(DrawingSpec(model=p.name), p)
    d0 = next(d for d in plan.dims if d.ref == "step0_dia")
    assert d0.text == "Φ27m6(+0.021/+0.008)"
    over = d0.extra["over_at"]
    rows = [d.extra["sheet_pos"][1] for d in plan.dims if d.view == "front" and (d.extra or {}).get("orient") == "h"]
    assert over > max(y for y in rows if y < over)  # 在上方尺寸行之上


@pytest.mark.parametrize("js", SPECS)
def test_fuzz_specs_compile_both_adapters(js):
    """排布回归样例同时走 SolidWorks / Creo 编译（零件 + 工程图），防止规划层坐标改动弄坏适配器翻译。"""
    from cadmcp.adapters.creo import compile as CC, drawing as CD
    from cadmcp.adapters.solidworks import compile as SW
    from cadmcp.errors import CadError
    spec = PartSpec.model_validate(json.loads(js))
    p = resolve_part(spec)
    plan = plan_part_drawing(DrawingSpec(model=p.name), p)
    assert SW.compile_part(spec, p) and SW.compile_drawing(plan, "m.sldprt")
    assert CD.compile_drawing(plan, "m.prt")
    try:
        assert CC.compile_part_tk(spec, p)
    except CadError as e:  # Creo TOOLKIT 首期不支持钣金/焊接件（文档已注明）
        assert e.code == "CAPABILITY_UNSUPPORTED" and json.loads(js)["base"]["type"] in ("sheet_metal", "weldment")


def test_short_shaft_tight_groove_enlarges():
    """短轴上挡圈槽紧挨轴肩，定位尺寸 6.85 在 1:1 下写不进两界线之间：A4 放得下 2:1 时放大画（不是默认 1:1）。"""
    p = resolve_part(PartSpec.model_validate(json.loads('{"name": "S18", "part_no": "S-18", "title": "测试轴", "material": "45#", "base": {"type": "shaft", "chamfer": 1, "steps": [{"length": 10, "diameter": 47, "tolerance": "f7"}, {"length": 10, "diameter": 50, "tolerance": "js6"}], "center_holes": {"type": "B"}}, "features": [{"feature": "groove", "name": "G1", "type": "circlip", "step": 1}]}')))
    plan = plan_part_drawing(DrawingSpec(model=p.name), p)
    assert plan.scale == 2.0 and plan.sheet == "A4"
    p2 = resolve_part(PartSpec.model_validate(json.loads('{"name": "S18", "part_no": "S-18", "title": "测试轴", "material": "45#", "base": {"type": "shaft", "chamfer": 1, "steps": [{"length": 10, "diameter": 47, "tolerance": "f7"}, {"length": 10, "diameter": 50, "tolerance": "js6"}], "center_holes": {"type": "B"}}, "features": [{"feature": "groove", "name": "G1", "type": "circlip", "step": 1}]}')))
    plan2 = plan_part_drawing(DrawingSpec(model=p2.name, sheet="A2"), p2)  # 指定大图幅：不因此放大
