def test_bore_ra_on_dim_line():
    """孔小、孔径文字伸出外轮廓：内孔 Ra 标在孔径尺寸线上（转 90°，尖端在尺寸线上、文字之后），
    外圆框格引线让开；SW / Creo 都按自由放置 + 旋转 90° 下发。"""
    from cadmcp.adapters.creo import drawing as CD
    from cadmcp.adapters.solidworks import compile as SW
    p = resolve_part(PartSpec.model_validate(json.loads('{"name": "S236", "part_no": "S-236", "title": "测试轴", "material": "45#", "base": {"type": "shaft", "chamfer": 1.5, "steps": [{"length": 25, "diameter": 30, "tolerance": "f7"}, {"length": 60, "diameter": 25, "tolerance": "js6"}], "bores": [{"diameter": 12, "tolerance": "H7"}]}, "features": [], "auto_precision": true}')))
    plan = plan_part_drawing(DrawingSpec(model=p.name), p)
    ra = next(d for d in plan.dims if d.ref == "ra:bore:0")
    dim = next(d for d in plan.dims if d.ref == "bore0_dia")
    assert ra.extra["rot"] == 90 and ra.extra["sheet_at"][0] == dim.extra["sheet_pts"][0][0]
    assert ra.extra["sheet_at"][1] > dim.extra["over_at"]
    _, out = render(plan, p)
    assert out["crossings"] == [] and out["collisions"] == []
    sw = next(o for o in SW.compile_drawing(plan, "m.sldprt") if o.op == "surface_finish" and o.args["ref"] == "ra:bore:0")
    assert sw.args["angle"] == 90 and sw.args["at"] is None and sw.args["leader"] is False
    cr = [o for o in CD.tk_detail_ops(plan) if o.op == "tk.drw.surface_finish" and o.args.get("angle") == 90]
    assert len(cr) == 1 and cr[0].args["at"] is None


def test_blind_bore_depth_not_collinear_with_top_row():
    """盲孔深度尺寸与上方键槽/环槽定位尺寸区间重叠时放到低一道（不共线重叠，高过剖切字母）。"""
    spec = '{"name": "S198", "part_no": "S-198", "title": "测试轴", "material": "45#", "base": {"type": "shaft", "chamfer": 1.5, "steps": [{"length": 40, "diameter": 35, "tolerance": "m6"}, {"length": 60, "diameter": 40}, {"length": 80, "diameter": 35, "tolerance": "js6"}, {"length": 20, "diameter": 27}, {"length": 25, "diameter": 24}, {"length": 40, "diameter": 21}], "bores": [{"diameter": 8, "length": 106, "tolerance": "H7"}]}, "features": [{"feature": "groove", "name": "G0", "type": "undercut", "step": 0}, {"feature": "keyway", "name": "K1", "step": 1, "length": 45}, {"feature": "keyway", "name": "K2", "step": 2, "length": 56}, {"feature": "groove", "name": "G3", "type": "grinding", "step": 3}, {"feature": "groove", "name": "G4", "type": "undercut", "step": 4}, {"feature": "keyway", "name": "K5", "step": 5, "length": 28}]}'
    p = resolve_part(PartSpec.model_validate(json.loads(spec)))
    plan = plan_part_drawing(DrawingSpec(model=p.name), p)
    hs = [(round(d.extra["sheet_pos"][1], 1), *sorted(q[0] for q in d.extra["sheet_pts"]), d.ref) for d in plan.dims
          if d.view == "front" and d.kind == "linear" and (d.extra or {}).get("orient") == "h" and "sheet_pts" in d.extra]
    assert not [(a[3], b[3]) for k, a in enumerate(hs) for b in hs[k + 1:]
                if a[0] == b[0] and a[1] < b[2] - 0.5 and b[1] < a[2] - 0.5]
    bd = next(d for d in plan.dims if d.ref.endswith("_depth"))
    assert bd.extra.get("track") == 1


def test_shaft_datum_aligned_with_dia_line_and_cut_z():
    """轴段基准与直径尺寸线对齐（基准为轴线）；剖切位置写入 ViewPlan.cut_z，SW/Creo 共用。"""
    spec = {"name": "S", "part_no": "S", "title": "轴", "material": "45#",
            "base": {"type": "shaft", "chamfer": 1, "steps": [{"length": 30, "diameter": 30, "tolerance": "k6"},
                                                              {"length": 40, "diameter": 36},
                                                              {"length": 30, "diameter": 30, "tolerance": "k6"}]},
            "features": [{"feature": "keyway", "name": "K1", "step": 1, "length": 28}], "auto_precision": True}
    p = resolve_part(PartSpec.model_validate(spec))
    plan = plan_part_drawing(DrawingSpec(model=p.name), p)
    dias = {d.ref: d.extra["sheet_pts"][0][0] for d in plan.dims if d.kind == "diameter" and d.ref.startswith("step")}
    dts = [d for d in plan.dims if d.kind == "datum" and d.view == "front"]
    assert dts
    for d in dts:
        i = int(next(x["target"] for x in p.datums if x["name"] == d.text)[5:])
        assert abs(d.extra["sheet_at"][0] - dias[f"step{i}_dia"]) < 0.01
    sec = [v for v in plan.views if v.type == "section"]
    assert sec and sec[0].cut_z is not None
    from cadmcp.adapters.creo.drawing import shaft_section_z
    assert shaft_section_z(plan, sec[0]) == sec[0].cut_z


